// Real-world geographic vector boundaries and mathematical projection engine
// Source: Natural Earth 1:110m vector dataset
// All coordinates projected using Equirectangular (Plate Carrée) projection

export interface GeoPoint {
  x: number;
  y: number;
}

export interface DestinationRoute {
  id: string;
  country: string;
  city: string;
  code: string;
  flag: string;
  lat: number;
  lon: number;
  duration: number;
  delay: number;
  universities: string;
}

export const MAP_CONFIG = {
  width: 1200,
  height: 650,
  minLon: -180,
  maxLon: 180,
  minLat: -60,
  maxLat: 82,
} as const;

/**
 * Converts real-world latitude and longitude to SVG viewBox coordinates.
 * Formula:
 * x = ((lon - minLon) / (maxLon - minLon)) * width
 * y = ((maxLat - lat) / (maxLat - minLat)) * height
 */
export function projectGeo(lon: number, lat: number): GeoPoint {
  const x = ((lon - MAP_CONFIG.minLon) / (MAP_CONFIG.maxLon - MAP_CONFIG.minLon)) * MAP_CONFIG.width;
  const y = ((MAP_CONFIG.maxLat - lat) / (MAP_CONFIG.maxLat - MAP_CONFIG.minLat)) * MAP_CONFIG.height;
  return {
    x: Math.round(x * 10) / 10,
    y: Math.round(y * 10) / 10,
  };
}

