/**
 * Computes an authentic aviation curved flight path between origin and destination.
 */
export function getFlightArc(origin: GeoPoint, target: GeoPoint, isAustralia = false): {
  pathD: string;
  controlX: number;
  controlY: number;
} {
  const dx = target.x - origin.x;
  const dy = target.y - origin.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  let controlX: number;
  let controlY: number;

  if (isAustralia) {
    // Graceful curve south-east
    controlX = (origin.x + target.x) / 2 + 35;
    controlY = (origin.y + target.y) / 2 - 35;
  } else if (target.x < 450) {
    // Long transatlantic / US route: higher northern arch
    controlX = (origin.x + target.x) / 2;
    controlY = Math.min(origin.y, target.y) - dist * 0.35;
  } else {
    // European corridors: elegant high-altitude northern arch
    controlX = (origin.x + target.x) / 2;
    controlY = Math.min(origin.y, target.y) - dist * 0.16;
  }

  controlX = Math.round(controlX * 10) / 10;
  controlY = Math.round(controlY * 10) / 10;

  return {
    pathD: `M ${origin.x} ${origin.y} Q ${controlX} ${controlY} ${target.x} ${target.y}`,
    controlX,
    controlY,
  };
}

